definition.script:
pipeline {
    agent any

    parameters {
        choice(
            name: 'Env',
            choices: ['Dev', 'QA', 'Prod'],
            description: 'Environment'
        )
    }

    stages {
        stage('Hello') {
            steps {
                echo 'Hello'
            }
        }

        stage('Deploy') {
            steps {
                script {
                    if (params.Env == 'Dev') {
                        sh 'echo Dev'
                    }
                    else if (params.Env == 'QA') {
                        sh 'echo QA'
                    }
                    else {
                        sh 'echo Prod'
                    }
                }

                echo 'mvn test'
            }
        }

        stage('Build') {
            steps {
                echo 'mvn package'
            }
        }
    }
}
